pub use manifest::kernel::{
    decode_presence_peer,
    encode_presence_peer,
    ActionContext,
    ActionDef,
    ActionId,
    ActionInvocation,
    ActionRequest,
    ActorId,
    AppEvent,
    AppInstanceId,
    Appearance,
    ArtifactDiff,
    ArtifactHandle,
    ArtifactId,
    ArtifactKind,
    ArtifactVersion,
    AssetHandle,
    Capability,
    CapabilityGrant,
    CapabilityRequirement,
