    // `semio_framework_plugin::RequestId` without a separate import.
    RequestId,
    Rights,
    SchemaId,
    SchemaVersion,
    Scope,
    UndoGroup,
    UndoPolicy,
    WindowEvent,
    WindowHandle,
    WindowInput,
    WindowKindDef,
    WindowKindId,
    WindowOutput,
};
