    SPEC.get_or_init(|| spec(vec![field(1, "identity", Shape::Record(identity_spec_producer())), field(2, "clear", Shape::Bool), field(3, "next", Shape::UInt), field(4, "pages", Shape::List(Box::new(Shape::Bytes64))).optional()]))
}

