// component target.
#[cfg(all(target_arch = "wasm32", not(target_env = "p2")))]
use semio_framework_async::browser::future_to_promise;
#[cfg(all(target_arch = "wasm32", not(target_env = "p2")))]
use std::cell::RefCell;
