  }
  let cursor = 0;
  await Promise.all(Array.from({ length: Math.min(32, jobs.length) }, async () => {
    for (;;) {
      const index = cursor++;
      if (index >= jobs.length) return;
      const { name, file } = jobs[index], sourceFile = nxPath(file.file);
