        let text;
        try { text = await readFile(join(workspaceRoot, sourceFile), "utf8"); }
        catch (error) { if (error.code === "ENOENT") continue; throw error; }
        identity ??= moduleSourceFactIdentity(sourceFile, createHash("sha256").update(text).digest("hex"));
