      } else {
        text = operators.find((operator) => this.source.startsWith(operator, start)) ?? first;
        if (!/^[{}()[\].,;:?~!+\-*/%<>=&|^]$/u.test(text) && !operators.includes(text)) throw new TypeScriptDeclarationRecovery(start);
