    .replace(/#!?\[[^\]]*\]/gu, "")
    .replace(/(?:pub(?:\([^)]*\))?\s+)?(?:unsafe\s+)?extern\s+crate\s+[^;]+;/gu, "")
    .replace(/(?:pub(?:\([^)]*\))?\s+)?use\s+[^;]+;/gu, "")
    .replace(/(?:pub(?:\([^)]*\))?\s+)?(?:mod|type)\s+[^;{}]+;/gu, "")
    .replace(/\binclude!?\s*\([^;]+;/gu, "")
