    if (defaults) values = values.slice(0, assignment);
    if (values[0]?.kind === "identifier") return { names: [values[0].text], defaults, destructured: false };
    if (!(["{", "["].includes(values[0]?.text ?? "") && ["}", "]"].includes(values.at(-1)?.text ?? ""))) return null;
    const names: string[] = [];
